// ---------------------------------------------------------------------
// NORMALIZE LEAD
// Four capture sources feed this one workflow. Each sends a slightly
// different payload shape. This node is the only place that knows about
// those differences. Everything downstream sees one canonical schema.
//
// This is the "one workflow, four entry points" decision. The alternative
// is four near-identical workflows that drift apart within a quarter.
// ---------------------------------------------------------------------

const raw = $input.item.json.body ?? $input.item.json;

// Source-specific field aliases. Adding a fifth capture source is a new
// entry in this map, not a new workflow.
const SOURCE_MAP = {
  inbound_hand_raiser:  { email: 'email',          company: 'company',          minutes: 'engagement_minutes' },
  content_download:     { email: 'work_email',     company: 'company_name',     minutes: 'session_minutes' },
  engagement_threshold: { email: 'email',          company: 'account_name',     minutes: 'total_minutes' },
  event:                { email: 'attendee_email', company: 'attendee_company', minutes: 'booth_minutes' }
};

const source = String(raw.lead_source || 'inbound_hand_raiser').toLowerCase();
const map = SOURCE_MAP[source] || SOURCE_MAP.inbound_hand_raiser;

const str = (v) => (typeof v === 'string' ? v.trim() : (v ?? null));
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

const email = str(raw[map.email]);

return {
  json: {
    // Identity. Email is the source of truth for dedupe and it is
    // lowercased here, at capture, so nothing downstream has to guess.
    email: email ? email.toLowerCase() : null,
    company: str(raw[map.company]),

    // Capture context
    lead_source: source,
    captured_at: raw.captured_at || new Date().toISOString(),

    // Engagement signal
    engagement_minutes: num(raw[map.minutes]),
    conversion_event: str(raw.conversion_event),

    // Firmographics used for routing
    employee_count: num(raw.employee_count),
    existing_account_owner: str(raw.existing_account_owner),

    // Brand / product attribution, populated at capture from UTM params.
    // Inferring brand later is how a shared multi-brand instance bleeds
    // together. Set it once, at the form, or you never trust it again.
    product: str(raw.product) || str(raw.utm_content),
    utm_source: str(raw.utm_source),
    utm_campaign: str(raw.utm_campaign)
  }
};

// ---------------------------------------------------------------------
// SCORE & QUALIFY
// One pure function. Given a normalized lead, decide two things:
//   1. Is this an MQA?
//   2. Who owns it?
//
// Deliberately no branching on the canvas. Canvas branches are where
// this kind of workflow rots: each branch accumulates its own slightly
// different logic until nobody can say what the rules are. Adding a
// fourth segment here is one row in ROUTING_TABLE.
// ---------------------------------------------------------------------

const lead = $input.item.json;

// --- Definitions -----------------------------------------------------
// These are the contract between marketing and sales. They live in code
// and in the SOP, and they match. That is the whole point.
const MQA_MINUTES_THRESHOLD = 100;   // rolling 3-month window
const ENTERPRISE_HEADCOUNT  = 500;

const HIGH_VALUE_EVENTS = [
  'demo_request',
  'pricing_contact',
  'trial_started'
];

// --- Qualification ---------------------------------------------------
const met_threshold = lead.engagement_minutes >= MQA_MINUTES_THRESHOLD;
const high_value    = HIGH_VALUE_EVENTS.includes(lead.conversion_event);
const is_mqa        = met_threshold || high_value;

// Always record *why*. An MQA you cannot explain is an MQA sales will
// argue with.
const qualification_reason = high_value
  ? 'high_value_event:' + lead.conversion_event
  : met_threshold
    ? 'engagement_threshold:' + lead.engagement_minutes + 'min'
    : 'below_threshold:' + lead.engagement_minutes + 'min';

// --- Segment ---------------------------------------------------------
// Order matters. An existing owner outranks firmographics every time --
// routing a named account to a new BDR is the fastest way to lose the
// sales team's trust in the whole system.
const segment = lead.existing_account_owner
  ? 'existing_owner'
  : lead.employee_count >= ENTERPRISE_HEADCOUNT
    ? 'enterprise'
    : 'mid_market';

// --- Routing table ---------------------------------------------------
const ROUTING_TABLE = {
  existing_owner: {
    owner_role: 'account_owner',
    slack_channel: '#leads-named-accounts',
    salesloft_cadence: 'existing-account-reengage'
  },
  enterprise: {
    owner_role: 'bdr',
    slack_channel: '#leads-enterprise',
    salesloft_cadence: 'enterprise-outbound-v3'
  },
  mid_market: {
    owner_role: 'isr',
    slack_channel: '#leads-mid-market',
    salesloft_cadence: 'mid-market-inbound-v2'
  }
};

return {
  json: {
    ...lead,
    is_mqa,
    qualification_reason,

    // How far off was this lead? Computed HERE, next to the constant that
    // defines it, so there is exactly one place the threshold rule lives.
    // Downstream nodes read this value instead of re-deriving it.
    minutes_to_threshold: Math.max(0, MQA_MINUTES_THRESHOLD - lead.engagement_minutes),

    segment,
    lifecycle_stage: is_mqa ? 'Qualified' : 'Validated',
    route: ROUTING_TABLE[segment]
  }
};

// ---------------------------------------------------------------------
// BUILD SALES HANDOFF
// Constructs the payloads for Slack and SalesLoft. Nothing is actually
// sent from here, on purpose: this repo is the decision layer, and the
// decision layer is the part worth reviewing.
//
// To make it live, replace this node with two HTTP Request nodes and
// point them at a Slack incoming webhook and the SalesLoft API.
// ---------------------------------------------------------------------

const lead = $input.item.json;
const company = lead.company || 'unknown company';

return {
  json: {
    decision: 'route_to_sales',
    lifecycle_stage: lead.lifecycle_stage,
    assign_to: lead.route.owner_role,

    salesloft: {
      cadence: lead.route.salesloft_cadence,
      person: { email: lead.email, company: lead.company }
    },

    slack: {
      channel: lead.route.slack_channel,
      text: [
        '*New MQA - ' + lead.segment.replace(/_/g, ' ') + '*',
        lead.email + ' | ' + company,
        'Source: ' + lead.lead_source + ' | Why: ' + lead.qualification_reason
      ].join('\n')
    },

    // Every decision writes an audit record. If you cannot reconstruct
    // why a lead went where it went, you cannot debug the funnel.
    audit: {
      email: lead.email,
      segment: lead.segment,
      qualification_reason: lead.qualification_reason,
      captured_at: lead.captured_at,
      product: lead.product
    }
  }
};

// ---------------------------------------------------------------------
// ASSIGN NURTURE TRACK
// Not an MQA yet. It still gets a home. Leads that fall out of routing
// with no track assigned are how a database quietly rots -- they are not
// lost, they are just invisible, which is worse.
//
// Note: this node deliberately does NOT know the MQA threshold. Score &
// Qualify owns that rule and passes the result down. An earlier version
// declared the constant a second time here, which meant changing the
// threshold upstream left this number silently reporting a stale value.
// ---------------------------------------------------------------------

const lead = $input.item.json;

const NURTURE_TRACKS = {
  inbound_hand_raiser:  'hand-raiser-warmup',
  content_download:     'content-topic-followup',
  engagement_threshold: 'engagement-accelerate',
  event:                'post-event-followup'
};

return {
  json: {
    decision: 'route_to_nurture',
    lifecycle_stage: lead.lifecycle_stage,
    nurture_track: NURTURE_TRACKS[lead.lead_source] || 'general-nurture',

    // Useful for reporting: how close was this lead to qualifying?
    // Computed upstream, where the threshold constant actually lives.
    minutes_to_threshold: lead.minutes_to_threshold,

    audit: {
      email: lead.email,
      segment: lead.segment,
      qualification_reason: lead.qualification_reason,
      captured_at: lead.captured_at,
      product: lead.product
    }
  }
};
